"""Write exact-template task reports from evidence, never from guessed outcomes."""
import csv
import json
from evidence import OUT, DOCS
from analyze import matrix, events, segments

def write(filename, title, question, why, method, results, evidence, confidence, risks, followups):
    (DOCS / filename).write_text(f"# {title}\nQuestion: {question}\nWhy it matters for the sync layer: {why}\nMethod: {method}\nResults:\n\n{results}\n\nEvidence: {evidence}\nConfidence: {confidence}\nSurprises / risks found: {risks}\nOpen follow-ups: {followups}\n", encoding="utf-8")

def observation():
    tables = []
    for version in ["5.7", "5.8"]:
        matrix(version)
        with (DOCS / f"evidence/T08-{version}-matrix.csv").open() as handle:
            rows = list(csv.reader(handle))
        tables.append(f"**UE {version}: counts across all observed objects in each scenario window**\n\n| Source | Modified | Property | Transacted | Table | Dirty transition | Marked dirty | PostUndo | PostRedo | Tx state | Thread | Property / transacted names |\n| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |")
        for row in rows[1:]:
            tables.append("| " + " | ".join(row[:10] + ["game" if row[10] == "True" else "none/mixed", f"{row[11] or '—'} / {row[12] or '—'}"]) + " |")
        tables.append("")
    write("T08-observation-matrix.md", "T08 — Observation matrix", "Which real scripted editor actions broadcast the available hooks?", "Reverse synchronization must observe every supported editing path and define blind spots.", "`python research/sync-probe/live.py 5.7 matrix`; close editor; launch 5.8; `python research/sync-probe/live.py 5.8 matrix`; `python research/sync-probe/analyze.py`. Mark delimiters isolate scenarios. C++ helpers in probe implement FDataTableEditorUtils row actions and PreEditChange/PostEditChangeProperty dataasset/actor equivalents. Interactive scenario emits three Interactive events and SnapshotTransactionBuffer, then ValueSet. It is a scripted equivalent, not an actual slider drag. RC writes wait 1.5s before next marker to capture delayed finalization. Five tables: Scalars, ScalarsOverride, Structs, RightReferences, Text. Counts include dependent CompositeDataTable events and auxiliary objects; they are not one notification per requested table. CSV retains exact event types/properties. Raw mutation success alone is not UI observation.", "\n".join(tables) + "\nAll recorded hooks in both runs were on the game thread. Event type integers: UndoRedo=0, Finalized=1, Snapshot=2. Property Changed `None` means the event carried no property. A raw pointer cell mutation fired zero requested hooks. Apply itself fired transaction notifications but **zero per-table change delegates and zero property-change events**. Save only produced a dirty transition among these hooks. Cancel generated TransactionStarted/Canceled and table events, but no finalized transaction; it leaves mutated bytes (confirmed separately in T10). Reload has no transaction and the old per-table subscription does not transfer to the replacement object.\n\nNative row serialization produced property names in transaction events despite RowMap not being a UPROPERTY: one Count cell scenario named **Count and Enabled**, add/remove/reorder named all scalar fields, and Label-only edit also named Nested. These names are coarse and can include untouched fields; no row name or old/new field value appeared. Source-only assumptions that native rows necessarily give an empty property list are contradicted by these logs. Diffing remains necessary to identify exact cells.\n\n**NEEDS HUMAN:** real DataTable editor cell controls, modal dialogs, PIE interactions, genuine mouse slider pacing and a dirty-package reload/revert. Reproduce with Mark, perform the UI operation, then inspect the same JSONL. Scripted reload here followed Save, so it reloads a clean package, not an unsaved revert.", "[5.7 CSV](evidence/T08-5.7-matrix.csv), [5.8 CSV](evidence/T08-5.8-matrix.csv), [5.7 sample](evidence/T08-5.7-sample.jsonl), [5.8 sample](evidence/T08-5.8-sample.jsonl). Raw `out/sync-research/{5.7,5.8}/matrix-events.jsonl`, `matrix-summary.json`, `T08-rpc.jsonl`.", "high for exact scripted runs on both engines; low for real UI/modal/PIE equivalence, explicitly untested.", "Apply has no table delegate signal; transaction field lists are broader than true cells. Delegate multiplicity includes dependent tables. Pointer writes evade the whole observer. Saved only the disposable DT_Scalars.uasset copies; tracked content untouched.", "Test actual widgets and reload/revert of unsaved content; add package reload lifecycle observation/resubscription; coalesce finalized/undo notifications once per operation.")

if __name__ == "__main__":
    observation()
